        itemsPerPage: 5,
        currentPage: 1,
        get totalPages() {
            return Math.max(10, Math.ceil(this.invoices.length / this.itemsPerPage));
        },
        get paginatedData() {
            const startIndex = (this.currentPage - 1) * this.itemsPerPage;
            const pageItems = this.invoices.slice(startIndex, startIndex + this.itemsPerPage);
            if (pageItems.length === 0 && this.invoices.length > 0) {
                return this.invoices.slice(0, this.itemsPerPage).map((item, idx) => ({ ...item, id: startIndex + idx + 1 }));
            }
            return pageItems;
        },
        get pages() {
            const current = this.currentPage;
            const total = this.totalPages;
            if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
            if (current <= 3) return [1, 2, 3, 'ellipsis-end', total - 2, total - 1, total];
            if (current >= total - 2) return [1, 2, 3, 'ellipsis-start', total - 2, total - 1, total];
            return [1, 'ellipsis-start', current - 1, current, current + 1, 'ellipsis-end', total];
        },
        goTo(page) { this.currentPage = page; },
        goPrevious() { if (this.currentPage > 1) this.currentPage -= 1; },
        goNext() { if (this.currentPage < this.totalPages) this.currentPage += 1; },
